export async function resolve(input,api) {
 const response=await api.request({url:input.url,headers:{"User-Agent":"AsterLink-source-test"}});
 const repo=JSON.parse(response.text);
 if(repo.name!=="quickjs") throw new Error("Unexpected repository");
 return {title:repo.name,items:[{id:"v0.14.0",name:"quickjs-v0.14.0.zip",kind:"file"}]};
}
export function download(){return {urls:["https://codeload.github.com/quickjs-ng/quickjs/zip/refs/tags/v0.14.0"]};}

export async function resolve(input,api) {
 const response=await api.request({url:input.url,redirects:true});
 const page=await api.html(response.text,{links:{selector:'a[href="./rfc20"]',attributes:["href"],limit:1}});
 const items=[];
 for(const row of page.links) items.push({id:"rfc20",name:"rfc20.txt",kind:"file",url:await api.codec("urlResolve",[input.url,row.href+".txt"])});
 return {title:"RFC 20",items};
}
export function download(input){return {urls:[input.resource.url]};}

import {signatureInput} from "./sign.js";
export async function resolve(input,api) {
 const sign=await api.crypto("hash",["sha256",signatureInput(input.url)]);
 const response=await api.request({url:input.url,method:"POST",body:{token:sign}});
 const data=JSON.parse(response.text);
 if(data.json.token!==sign)throw new Error("Signature echo mismatch");
 return {items:[{id:"test",name:"source-runtime.txt",kind:"file",size:20}]};
}
export function download(){return {urls:["https://httpbingo.org/base64/U291cmNlIHJ1bnRpbWUgdGVzdAo="]};}
